// Paged tutorial pop-up: shows the Message_PC columns of one tutorial.2da row and runs the
// combat action the tutorial demonstrates once the player dismisses the last page.

#ifndef CSWGUITUTORIALBOX_H
#define CSWGUITUTORIALBOX_H
#include "k2stdint.h"

#include "swguiingame.h"

class CSWGuiManager;

class CSWGuiTutorialBox : public CSWGuiMessageBox {
public:
    // <VTABLE-GEN: binary ground truth (_ZTV) — regenerated by tools/hoist_headers.py; do not edit inside markers */
    //   primary vtable, 36 slots
    virtual void HandleInputEvent(int nType, int nValue);
    virtual void OnPanelAdded();
    virtual void SetMessage(uint64_t nStrRef);
    // </VTABLE-GEN>
    using CSWGuiMessageBox::SetMessage;

    CSWGuiTutorialBox(CSWGuiManager* pGuiManager);

    int  SetNextMessage();
    int  TutorialReasonIsValid(unsigned char reason);
    int  SetTutorialReason(unsigned char reason);
    void SetTutorialInstigator(unsigned long long instigatorId,
                               unsigned long long targetId, unsigned int type);

    void MessageBoxPause(CSWGuiControl* pControl);
    void MessageBoxUnpause(CSWGuiControl* pControl);
    void PerformCombatFeat(CSWGuiControl* pControl);
    void PerformUseGrenade(CSWGuiControl* pControl);
    void PerformSetMine(CSWGuiControl* pControl);
    void PerformForcePower(CSWGuiControl* pControl);
    void PerformPlayerFlourishWeapons(CSWGuiControl* pControl);
    void PerformBash(CSWGuiControl* pControl);
    void PerformAttack(CSWGuiControl* pControl);
    void PerformNonCombatXButton(CSWGuiControl* pControl);
    void PerformCombatXButton(CSWGuiControl* pControl);
    void PerformCombatYButton(CSWGuiControl* pControl);
    void PerformReturnToBase(CSWGuiControl* pControl);

    unsigned long long m_instigatorId;
    unsigned long long m_targetId;
    unsigned int m_type;
    int m_bCombatWasPaused;
    unsigned char m_nTutorialReason;
    unsigned char m_nMessageIndex;
};

#if !KOTOR1  // K1's GUI base classes are smaller
K2_LAYOUT_ASSERT(sizeof(CSWGuiTutorialBox) == 0xda8, "CSWGuiTutorialBox size drift");
#endif

#endif
